ee:message.ee:set-payload:
%dw 2.0
output application/xml
---
{
    BAPI_CUSTOMER_GETLIST: {
        "import": {
            MAXROWS: "100"
        },
        tables: {
            IDRANGE: {
                row: {
                    SIGN: "I",
                    OPTION: "BT",
                    LOW: "0",
                    HIGH: "999999999"
                }
            }
        }
    }
}

%dw 2.0
output application/json

// Convert XML values to strings, omitting empty values.
fun optionalString(value) =
    if (isEmpty(trim((value default "") as String)))
        null
    else
        trim(value as String)

// Map an SAP ECC customer record to the API data model.
fun mapCustomer(customer) =
    {
        sapCustomerNumber: (customer.CUSTOMER default "") as String,
        nameLine1: (customer.NAME default "") as String,

        (searchTerm: optionalString(customer.SORT1))
            if (optionalString(customer.SORT1) != null),

        (streetAddress: optionalString(customer.STREET))
            if (optionalString(customer.STREET) != null),

        (city: optionalString(customer.CITY))
            if (optionalString(customer.CITY) != null),

        (region: optionalString(customer.REGION))
            if (optionalString(customer.REGION) != null),

        (postalCode: optionalString(customer.POSTL_COD1))
            if (optionalString(customer.POSTL_COD1) != null),

        (countryCode: optionalString(customer.COUNTRY))
            if (optionalString(customer.COUNTRY) != null),

        (phoneNumber: optionalString(customer.TEL1_NUMBR))
            if (optionalString(customer.TEL1_NUMBR) != null)
    }

var customers =
    payload.BAPI_CUSTOMER_GETLIST.tables.ADDRESSDATA.*row
        map (customer) -> mapCustomer(customer)

---
{
    dateTime: now() >> "UTC",
    httpStatus: 200,
    status: "SUCCESS",
    message: "Customer records retrieved successfully",
    correlationId: correlationId,
    data: {
        customers: customers,
        recordCount: sizeOf(customers)
    }
}
